import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor weight,
                              c10::optional<torch::Tensor> bias,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void conv3d_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K, int stride, int padding, int dilation,
    int Dout, int Hout, int Wout,
    int DoutTiles, int HoutTiles, int WoutTiles,
    int id_size, int ih_size, int iw_size)
{
  constexpr int Threads    = 128;
  constexpr int CcPerBlock = 64;
  constexpr int TD = 4;
  constexpr int TH = 4;
  constexpr int TW = 8;
  extern __shared__ float smem_raw[];
  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int co_tile = blockIdx.y;
  const int co_base = co_tile * CcPerBlock;
  // Decode spatial tile index
  int tile_idx = blockIdx.x;
  const int wt = tile_idx % WoutTiles;
  tile_idx /= WoutTiles;
  const int ht = tile_idx % HoutTiles;
  const int dt = tile_idx / HoutTiles;
  const int od_base = dt * TD;
  const int oh_base = ht * TH;
  const int ow_base = wt * TW;
  const int id_base = od_base * stride - padding;
  const int ih_base = oh_base * stride - padding;
  const int iw_base = ow_base * stride - padding;
  const int K2 = K * K;
  const int K3 = K2 * K;
  const int weight_per_channel = Cin * K3;
  const int sW_size = CcPerBlock * weight_per_channel;
  const int sX_size = Cin * id_size * ih_size * iw_size;
  float* sW_raw = smem_raw;
  float* sX_raw = smem_raw + sW_size;
  // Strides for global tensors (contiguous NCDHW layouts)
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride((int64_t)Dout*Hout*Wout, (int64_t)Hout*Wout, (int64_t)Wout, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(Wt),
      make_shape(Cout, Cin, K, K, K),
      make_stride((int64_t)Cin*K3, (int64_t)K3, (int64_t)K2, (int64_t)K, Int<1>{})
  );
  // Shared memory tensor: (Cin, K, K, K, CcPerBlock) - cc contiguous for fast vectorized reads in compute loop
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Cin, K, K, K, CcPerBlock),
      make_stride(K3*CcPerBlock, K2*CcPerBlock, K*CcPerBlock, CcPerBlock, Int<1>{})
  );
  // Shared memory tensor for staged input tile (with implicit zero padding): (Cin, id_size, ih_size, iw_size)
  auto sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Cin, id_size, ih_size, iw_size),
      make_stride(id_size*ih_size*iw_size, ih_size*iw_size, iw_size, Int<1>{})
  );
  // Load weight tile into shared memory
  for (int idx = tid; idx < sW_size; idx += Threads) {
    int rem  = idx % weight_per_channel;
    int cc   = idx / weight_per_channel;
    int kw = rem % K;
    int rem2 = rem / K;
    int kh = rem2 % K;
    rem2 /= K;
    int kd = rem2 % K;
    int cin = rem2 / K;
    int co = co_base + cc;
    float val = 0.0f;
    if (co < Cout) {
      val = mW(co, cin, kd, kh, kw);
    }
    sW(cin, kd, kh, kw, cc) = val;
  }
  // Load input tile into shared memory, zero-filling out-of-bounds (implements padding once per tile)
  const int ihw_size = ih_size * iw_size;
  const int idhw_size = id_size * ihw_size;
  for (int idx = tid; idx < sX_size; idx += Threads) {
    int cin = idx / idhw_size;
    int rem = idx % idhw_size;
    int idl = rem / ihw_size;
    int rem2 = rem % ihw_size;
    int ihl = rem2 / iw_size;
    int iwl = rem2 % iw_size;
    int id_g = id_base + idl;
    int ih_g = ih_base + ihl;
    int iw_g = iw_base + iwl;
    float val = 0.0f;
    if ((unsigned)id_g < (unsigned)D && (unsigned)ih_g < (unsigned)H && (unsigned)iw_g < (unsigned)Win) {
      val = mX(cin, id_g, ih_g, iw_g);
    }
    sX(cin, idl, ihl, iwl) = val;
  }
  __syncthreads();
  // Decode this thread's output coordinate within the spatial tile
  const int ow_local = tid % TW;
  const int tmp_idx  = tid / TW;
  const int oh_local = tmp_idx % TH;
  const int od_local = tmp_idx / TH;
  const int od = od_base + od_local;
  const int oh = oh_base + oh_local;
  const int ow = ow_base + ow_local;
  const bool valid = (od < Dout) && (oh < Hout) && (ow < Wout);
  // Accumulators, init with bias
  float acc[CcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int co = co_base + cc;
    acc[cc] = (Bias != nullptr && co < Cout) ? Bias[co] : 0.0f;
  }
  // Main compute loop: reads only from shared memory (no redundant global loads)
  if (valid) {
    for (int cin = 0; cin < Cin; ++cin) {
      for (int kd = 0; kd < K; ++kd) {
        int idl = od_local * stride + kd * dilation;
        for (int kh = 0; kh < K; ++kh) {
          int ihl = oh_local * stride + kh * dilation;
          for (int kw = 0; kw < K; ++kw) {
            int iwl = ow_local * stride + kw * dilation;
            float xval = sX(cin, idl, ihl, iwl);
            const float4* wrow = reinterpret_cast<const float4*>(&sW(cin, kd, kh, kw, 0));
            #pragma unroll
            for (int cc4 = 0; cc4 < CcPerBlock / 4; ++cc4) {
              float4 w4 = wrow[cc4];
              acc[cc4 * 4 + 0] += xval * w4.x;
              acc[cc4 * 4 + 1] += xval * w4.y;
              acc[cc4 * 4 + 2] += xval * w4.z;
              acc[cc4 * 4 + 3] += xval * w4.w;
            }
          }
        }
      }
    }
  }
  // Write outputs
  if (valid) {
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int co = co_base + cc;
      if (co < Cout) {
        mY(co, od, oh, ow) = acc[cc];
      }
    }
  }
}
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor weight,
                              c10::optional<torch::Tensor> bias,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(groups == 1, "only groups=1 is supported by this kernel");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cout, Cin, K, K, K]");
  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);
  int64_t Cout = weight.size(0);
  TORCH_CHECK(weight.size(1) == Cin, "weight.size(1) must equal Cin (groups=1)");
  int64_t K = weight.size(2);
  TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Dout = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());
  constexpr int Threads    = 128;
  constexpr int CcPerBlock = 64;
  constexpr int TD = 4;
  constexpr int TH = 4;
  constexpr int TW = 8;
  int DoutTiles = (int)((Dout + TD - 1) / TD);
  int HoutTiles = (int)((Hout + TH - 1) / TH);
  int WoutTiles = (int)((Wout + TW - 1) / TW);
  int spatial_tiles = DoutTiles * HoutTiles * WoutTiles;
  int id_size = (TD - 1) * stride + dilation * ((int)K - 1) + 1;
  int ih_size = (TH - 1) * stride + dilation * ((int)K - 1) + 1;
  int iw_size = (TW - 1) * stride + dilation * ((int)K - 1) + 1;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)spatial_tiles,
      (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );
  size_t sW_bytes = (size_t)CcPerBlock * Cin * K * K * K * sizeof(float);
  size_t sX_bytes = (size_t)Cin * id_size * ih_size * iw_size * sizeof(float);
  size_t smem_bytes = sW_bytes + sX_bytes;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
  }
  conv3d_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding, dilation,
      (int)Dout, (int)Hout, (int)Wout,
      DoutTiles, HoutTiles, WoutTiles,
      id_size, ih_size, iw_size
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution (square kernel, groups=1) implemented with a
    single custom CUDA kernel using CuTe tensors for cooperative tiled
    computation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert groups == 1, "This custom kernel only supports groups=1"

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * (self.kernel_size ** 3) // self.groups
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

